python3 - <<'PY'
import pathlib
p = pathlib.Path("src/codegen/lower_inst/method_resolution.rs")
s = p.read_text()
old = '''    if !ctx.is_main {
        return;
    }
    let Some((frame_name, arguments)) = internal_call_frame_shape(ctx, inst, class_name) else {
        return;
    };'''
new = '''    // A call that cannot THROW contributes no frame to anyone's trace, and recording one would do
    // worse than waste work: the buffer holds one trace at a time, so `$e->getTraceAsString()` —
    // itself a call into a builtin class — replaced the frames it was being asked to render with a
    // frame for the question.
    if !ctx.is_main || !inst.effects.contains(crate::ir::Effects::MAY_THROW) {
        return;
    }
    let Some((frame_name, arguments)) = internal_call_frame_shape(ctx, inst, class_name) else {
        return;
    };'''
assert s.count(old) == 1
p.write_text(s.replace(old, new))
print("recording gated on MAY_THROW")
